from fastapi import FastAPI
from fastapi.testclient import TestClient

app = FastAPI()


@app.get("/limited", rate_limit="50/minute")
def limited_endpoint():
    return {"ok": True}


@app.get("/unlimited")
def unlimited_endpoint():
    return {"ok": True}


client = TestClient(app)


def test_limited_endpoint_x_rate_limit_in_openapi():
    response = client.get("/openapi.json")
    assert response.status_code == 200, response.text
    schema = response.json()
    assert schema["paths"]["/limited"]["get"]["x-rate-limit"] == "50/minute"


def test_unlimited_endpoint_has_no_x_rate_limit_in_openapi():
    response = client.get("/openapi.json")
    assert response.status_code == 200, response.text
    schema = response.json()
    assert "x-rate-limit" not in schema["paths"]["/unlimited"]["get"]

